export function PermissionIcon({ name, className }: { name: PermissionIconName; className?: string }) {
  const icon: Icon = ICONS[name];
  return (
    <svg viewBox={icon.viewBox} fill="none" className={className} aria-hidden>
      {icon.shapes.map((shape) =>
        shape.fill ? (
          <path key={shape.d} d={shape.d} fill="currentColor" />
        ) : (
          <path
            key={shape.d}
            d={shape.d}
            stroke="currentColor"
            strokeWidth={shape.strokeWidth}
            strokeLinecap="round"
            strokeLinejoin={shape.strokeLinejoin}
          />
        )
      )}
    </svg>
  );
}
